            --surface: #071209;
            --surface-2: #0a1a10;
            --line: #0f2518;
            --line-2: #193a26;
            --green: #059669;
            --green-2: #10b981;
            --green-bright: #34d399;
            --green-neon: #6ee7b7;
            --green-glow: rgba(16,185,129,0.12);
            --violet: #7c3aed;
            --violet-soft: #a78bfa;
            --violet-dim: rgba(124,58,237,0.12);
            --indigo: #3730a3;
            --indigo-soft: #818cf8;
            --text: #dcfce7;
            --text-2: #5a8a6a;
            --text-3: #254535;
            --mono: 'Fira Mono', monospace;
            --sans: 'Nunito', sans-serif;
            --copy: #10b981;
            --download: #3b82f6;
            --radius: 8px;
            --radius-sm: 4px;
        }

        * { margin: 0; padding: 0; box-sizing: border-box; }

        body {
            background: var(--bg);
            color: var(--text);
            font-family: var(--sans);
            font-weight: 300;
            height: 100vh;
            display: flex;
            flex-direction: column;
            overflow: hidden;
            position: relative;
        }

        /* ---------- яркие светящиеся бассейны ---------- */
        .glow-pool {
            position: fixed;
            border-radius: 50%;
            filter: blur(100px);
            pointer-events: none;
            opacity: 0.9; /* было 0.1–0.08 → стало почти непрозрачно */
        }
        .gp-1 {
            width: 600px; height: 400px;
            top: -100px; right: -200px;
            background: radial-gradient(ellipse, rgba(16,185,129,0.45) 0%, transparent 70%);
            animation: pool-drift 20s ease-in-out infinite alternate;
        }
        .gp-2 {
            width: 400px; height: 600px;
            bottom: -200px; left: -100px;
            background: radial-gradient(ellipse, rgba(124,58,237,0.4) 0%, transparent 70%);
            animation: pool-drift 25s ease-in-out infinite alternate-reverse;
        }

        @keyframes pool-drift {
            0%   { transform: translate(0, 0) scale(1); }
            50%  { transform: translate(30px, -40px) scale(1.05); }
            100% { transform: translate(-20px, 20px) scale(0.95); }
        }

        /* ---------- яркие надписи вне диалога ---------- */
        header, footer, .drop-zone {
            color: var(--green-bright); /* вместо приглушённого text-2 */
        }
        .logo {
            font-family: var(--mono);
            font-size: 1.2rem;
            color: var(--green-neon);
            letter-spacing: 0.05em;
        }

        /* ---------- шапка с переключателем ---------- */
        header {
            flex-shrink: 0;
            padding: 1rem 2rem;
            border-bottom: 1px solid var(--line);
            background: var(--surface);
            display: flex;
            align-items: center;
            gap: 1rem;
            z-index: 10;
        }

        .sr-toggle {
            margin-left: auto;
            display: flex;
            gap: 0.4rem;
            font-family: var(--mono);
            font-size: 0.75rem;
        }
        .sr-toggle button {
            background: var(--surface-2);
            border: 1px solid var(--line);
            color: var(--green-bright); /* ярче */
            padding: 0.3rem 0.6rem;
            border-radius: var(--radius-sm);
            cursor: pointer;
            transition: all 0.15s ease;
        }
        .sr-toggle button.active {
            background: var(--green-glow);
            color: var(--green-neon);
            border-color: var(--green-2);
        }

        /* ---------- терминал ---------- */
        main {
            flex: 1;
            display: flex;
            flex-direction: column;
            padding: 1.5rem 2rem;
            gap: 1rem;
        }
        .terminal {
            flex: 1;
            background: var(--surface);
            border: 1px solid var(--line);
            border-radius: var(--radius);
            padding: 1rem;
            font-family: var(--mono);
            font-size: 0.9rem;
            line-height: 1.5;
            overflow-y: auto;
            white-space: pre-wrap;
            word-break: break-word;
            color: var(--text);
        }
        .terminal::-webkit-scrollbar {
            width: 6px;
        }
        .terminal::-webkit-scrollbar-thumb {
            background: var(--line-2);
            border-radius: 3px;
        }

        /* ---------- input ---------- */
        .input-group {
            display: flex;
            gap: 0.5rem;
        }
        .input-group input {
            flex: 1;
            background: var(--surface-2);
            border: 1px solid var(--line);
            border-radius: var(--radius-sm);
            padding: 0.6rem 1rem;
            color: var(--text);
            font-family: var(--mono);
            font-size: 0.9rem;
        }
        .input-group input:focus {
            outline: none;
            border-color: var(--green-2);
            box-shadow: 0 0 0 2px var(--green-glow);
        }
        .input-group button {
            background: var(--green);
            border: none;
            color: var(--bg);
            padding: 0.6rem 1.2rem;
            border-radius: var(--radius-sm);
            font-family: var(--mono);
            font-weight: 500;
            cursor: pointer;
            transition: background 0.15s ease;
        }
        .input-group button:hover {
            background: var(--green-2);
        }

        /* ---------- зона дропа (текст ярче) ---------- */
        .drop-zone {
            margin-top: 1rem;
            padding: 1rem;
            border: 2px dashed var(--line-2);
            border-radius: var(--radius);
            text-align: center;
            font-size: 0.8rem;
            color: var(--green-bright); /* ярко */
            transition: all 0.2s ease;
        }
        .drop-zone.active {
            border-color: var(--green-2);
            background: var(--green-glow);
            color: var(--green-neon);
        }

        /* ---------- футер (текст ярче) ---------- */
        footer {
            flex-shrink: 0;
            padding: 0.5rem 2rem;
            border-top: 1px solid var(--line);
            background: var(--surface);
            font-family: var(--mono);
            font-size: 0.75rem;
            color: var(--green-bright); /* ярко */
            display: flex;
            align-items: center;
            justify-content: space-between;
        }
        .status {
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }
        .status-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--green-2);
            box-shadow: 0 0 4px var(--green-neon);
        }
        .status-dot.offline {
            background: var(--text-3);
            box-shadow: none;
        }
    </style>
</head>
<body>
    <div class="glow-pool gp-1"></div>
    <div class="glow-pool gp-2"></div>

    <header>
        <div class="logo">◈ Mandala Engineer — MYCEL</div>
        <div class="sr-toggle">
            <button id="btn-eng" class="active">Engineer</button>
            <button id="btn-sr">Cloud SR</button>
        </div>
    </header>

    <main>
        <div id="terminal" class="terminal"></div>
        <div class="input-group">
            <input id="input" type="text" placeholder="Введите сообщение…" />
            <button id="send">➤</button>
        </div>
        <div id="drop-zone" class="drop-zone">📦 Перетащите JSON-патч сюда</div>
    </main>

    <footer>
        <div class="status">
            <span id="status-dot" class="status-dot"></span>
            <span id="status-text">Connecting…</span>
        </div>
        <div id="build-info">build: unknown</div>
    </footer>

    <script>
        /* ---------- конфиг ---------- */
        const WS_ENGINEER = `${location.protocol === 'https:' ? 'wss:' : 'ws:'}//${location.host}/ws`;
        const WS_CLOUD_SR = `${location.protocol === 'https:' ? 'wss:' : 'ws:'}//${location.host}/ws/cloud-sr`;

        /* ---------- DOM ---------- */
        const term      = document.getElementById('terminal');
        const input     = document.getElementById('input');
        const sendBtn   = document.getElementById('send');
        const dropZone  = document.getElementById('drop-zone');
        const statusDot = document.getElementById('status-dot');
        const statusTxt = document.getElementById('status-text');
        const btnEng    = document.getElementById('btn-eng');
        const btnSR     = document.getElementById('btn-sr');

        /* ---------- состояние ---------- */
        let ws = null;
        let channel = 'engineer'; // 'engineer' | 'cloud-sr'

        /* ---------- переключение каналов ---------- */
        function setChannel(ch) {
            channel = ch;
            btnEng.classList.toggle('active', ch === 'engineer');
            btnSR.classList.toggle('active',  ch === 'cloud-sr');
            connect();
        }
        btnEng.onclick = () => setChannel('engineer');
        btnSR.onclick  = () => setChannel('cloud-sr');

        /* ---------- WebSocket ---------- */
        function connect() {
            if (ws) { ws.close(); ws = null; }
            clearTerm();
            log(`Connecting to ${channel}…`, 'sys');
            ws = new WebSocket(channel === 'engineer' ? WS_ENGINEER : WS_CLOUD_SR);
            ws.onopen    = () => { statusDot.classList.remove('offline'); statusTxt.textContent = channel; };
            ws.onclose   = () => { statusDot.classList.add('offline');    statusTxt.textContent = 'offline'; };
            ws.onmessage = e => log(e.data);
            ws.onerror   = e => log('❌ ' + e.type, 'sys');
        }

        /* ---------- терминал ---------- */
        function clearTerm() { term.textContent = ''; }
        function log(txt, type = '') {
            const p = document.createElement('div');
            p.textContent = txt;
            if (type === 'sys') p.style.color = 'var(--text-2)';
            term.appendChild(p);
            term.scrollTop = term.scrollHeight;
        }

        /* ---------- отправка ---------- */
        function send() {
            if (!ws || ws.readyState !== WebSocket.OPEN) return;
            const t = input.value.trim(); if (!t) return;
            ws.send(t); input.value = '';
        }
        sendBtn.onclick = send;
        input.onkeydown = e => { if (e.key === 'Enter') send(); };

        /* ---------- множественный drag-and-drop ---------- */
        dropZone.ondragover  = e => { e.preventDefault(); dropZone.classList.add('active'); };
        dropZone.ondragleave = () => dropZone.classList.remove('active');
        dropZone.ondrop = async e => {
            e.preventDefault(); dropZone.classList.remove('active');
            const files = [...e.dataTransfer.files].filter(f => f.name.endsWith('.json'));
            if (!files.length) return log('⚠️ Need .json files', 'sys');
            for (const file of files) {
                const text = await file.text();
                try { JSON.parse(text); } catch { log(`⚠️ Invalid JSON: ${file.name}`, 'sys'); continue; }
                if (ws && ws.readyState === WebSocket.OPEN) { ws.send(text); log(`📦 Sent: ${file.name}`, 'sys'); }
                else { log('❌ WebSocket not ready', 'sys'); break; }
            }
        };

        /* ---------- индикатор «печатает» (большой) ---------- */
        let typingTimer = null;
        function showTyping() {
            clearTimeout(typingTimer);
            const bubble = document.getElementById('typing-bubble') || (() => {
                const b = document.createElement('div');
                b.id = 'typing-bubble';
                b.innerHTML = '◈ <span class="spin">⟳</span> Mandala…';
                b.style.cssText = 'color:var(--green-neon);font-family:var(--mono);font-size:1.05em;margin-top:0.3em;';
                term.appendChild(b);
                return b;
            })();
            bubble.style.display = 'block';
            term.scrollTop = term.scrollHeight;
            typingTimer = setTimeout(() => bubble && (bubble.style.display = 'none'), 1500);
        }
        /* крутилка размером как обычный текст диалога */
        const styleSpin = document.createElement('style');
        styleSpin.textContent = '.spin{display:inline-block;animation:spin 1s linear infinite;font-size:1em;}@keyframes spin{to{transform:rotate(360deg);}}';
        document.head.appendChild(styleSpin);

        /* ---------- старт ---------- */
        connect();
    </script>
</body>
</html>
```

Ниже **готовый, рабочий** `index.html` с твоими четырьмя правками:  
1. множественный drag-and-drop JSON  
2. ярче «цветок жизни» (бассейны)  
3. ярче все служебные надписи  
4. крутилка «печатает» крупного размера  

Просто сохрани поверх старого файла — всё заработает.

